/* ------------------------------------------------------------------------------------*/
/**
 * @brief gpu_demo_alpha_normal
 *
 * @param head
 *
 * @note: 带alpha的颜色需要开预乘，否则不显示或颜色异常
 */
/* ------------------------------------------------------------------------------------*/
static void gpu_demo_alpha_normal(pJLGPUTaskHead_t head)
{
    jlgpu_task_basic_param_init(GPU_TASK_IMAGE, 0x1, 0);
    task_param.format = GPU_FORMAT_A8;
    task_param.alpha = 0xff;
    task_param.blue = 0;
    task_param.red = 0xff;
    task_param.green = 0;
    task_param.image.width = 50;
    task_param.image.height = 50;

    task_param.draw.left = 100;
    task_param.draw.top = 100;
    task_param.draw.width = task_param.image.width;
    task_param.draw.height = task_param.image.height;
    jlgpu_get_win_rect(&task_param.area);
    task_param.texture.big_end = 0;
    task_param.texture.rbs = 0;
    task_param.texture.not_compress = 1;
    task_param.texture.data = test_image_a8;
    jlgpu_update_task_by_id(head, task_param.task_id, task_param.element_id, &task_param);

}

